scwin.checkWidth = function() {
    var width = ((j) => j.length ? j : $('#mf_gridView1_body_tbody'))($('#gridView1_body_tbody')).width() + ((j) => j.length ? j : $('#mf_gridView1_scrollY_div'))($('#gridView1_scrollY_div')).outerWidth();
    var win = window.innerWidth || document.documentElement.clientWidth || document.body.clientWidth;;
    if (width / win > 0.99) {
        return true;
    }
    return false;
}
